CREATE TABLE public.admin_activity_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL CHECK(event_type IN ('signup','pix_reported')), source_id uuid NOT NULL, title text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz, UNIQUE(event_type,source_id));
GRANT ALL ON public.admin_activity_notifications TO service_role;
ALTER TABLE public.admin_activity_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Service manages administrator activity" ON public.admin_activity_notifications FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE INDEX admin_activity_unread ON public.admin_activity_notifications(created_at DESC) WHERE read_at IS NULL;
CREATE FUNCTION public.notify_admin_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='profiles' THEN INSERT INTO public.admin_activity_notifications(event_type,source_id,title,body) VALUES('signup',NEW.id,'Novo usuário cadastrado',COALESCE(NULLIF(NEW.full_name,''),NEW.email,'Usuário') || ' criou uma conta no QAP Report.') ON CONFLICT(event_type,source_id) DO NOTHING; ELSIF TG_TABLE_NAME='pix_payment_requests' AND NEW.status='aguardando_aprovacao' THEN INSERT INTO public.admin_activity_notifications(event_type,source_id,title,body) VALUES('pix_reported',NEW.id,'Pix informado — aguardando aprovação',COALESCE(NEW.user_email,'Usuário') || ' informou pagamento de R$ ' || replace(to_char(NEW.amount_brl,'FM999999990.00'),'.',',') || '. Confira o comprovante antes de aprovar.') ON CONFLICT(event_type,source_id) DO NOTHING; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.notify_admin_activity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER profiles_notify_admin AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.notify_admin_activity();
CREATE TRIGGER pix_notify_admin AFTER INSERT ON public.pix_payment_requests FOR EACH ROW EXECUTE FUNCTION public.notify_admin_activity();